import React from "react";
import {
  FaUtensils,
  FaCar,
  FaShoppingBag,
  FaFilm,
  FaBolt,
  FaQuestionCircle,
} from "react-icons/fa";

const CategoryBudget = ({ expenses = [] }) => {
  // Default category budgets (can later be stored in MongoDB)
  const defaultBudgets = {
    Food: 8000,
    Transport: 3000,
    Shopping: 5000,
    Entertainment: 2500,
    Bills: 4000,
    Others: 2000,
  };

  // Category Icons
  const categoryIcons = {
    Food: <FaUtensils className="text-orange-400 text-2xl" />,
    Transport: <FaCar className="text-blue-400 text-2xl" />,
    Shopping: <FaShoppingBag className="text-pink-400 text-2xl" />,
    Entertainment: <FaFilm className="text-purple-400 text-2xl" />,
    Bills: <FaBolt className="text-yellow-400 text-2xl" />,
    Others: <FaQuestionCircle className="text-gray-400 text-2xl" />,
  };

  // Calculate spending by category
  const categoryMap = {};

  expenses.forEach((expense) => {
    const category = expense.category || "Others";

    if (!categoryMap[category]) {
      categoryMap[category] = {
        name: category,
        spent: 0,
        budget: defaultBudgets[category] || 3000,
      };
    }

    categoryMap[category].spent += Number(expense.amount || 0);
  });

  const categories = Object.values(categoryMap);

  return (
    <div className="bg-slate-800 rounded-3xl shadow-xl p-6 border border-slate-700 mt-8">

      <h2 className="text-3xl font-bold text-white mb-6">
        📂 Category Budget
      </h2>

      {categories.length === 0 ? (
        <div className="text-center text-gray-400 py-8">
          No expense data available.
        </div>
      ) : (
        <div className="space-y-5">
          {categories.map((category, index) => {
            const progress =
              (category.spent / category.budget) * 100;

            const remaining =
              category.budget - category.spent;

            return (
              <div
                key={index}
                className="bg-slate-700 rounded-2xl p-5"
              >
                <div className="flex justify-between items-center">

                  <div className="flex items-center gap-4">

                    {categoryIcons[category.name] ||
                      categoryIcons.Others}

                    <div>

                      <h3 className="text-white text-lg font-bold">
                        {category.name}
                      </h3>

                      <p className="text-gray-400">
                        Budget ₹
                        {category.budget.toLocaleString()}
                      </p>

                    </div>

                  </div>

                  <div className="text-right">

                    <p className="text-red-400 font-semibold">
                      Spent ₹
                      {category.spent.toLocaleString()}
                    </p>

                    <p
                      className={`font-semibold ${
                        remaining >= 0
                          ? "text-green-400"
                          : "text-red-400"
                      }`}
                    >
                      Remaining ₹
                      {remaining.toLocaleString()}
                    </p>

                  </div>

                </div>

                {/* Progress */}

                <div className="mt-5">

                  <div className="flex justify-between text-sm text-gray-300 mb-2">

                    <span>Usage</span>

                    <span>
                      {progress.toFixed(1)}%
                    </span>

                  </div>

                  <div className="w-full bg-slate-600 rounded-full h-3">

                    <div
                      className={`h-3 rounded-full transition-all duration-700 ${
                        progress < 80
                          ? "bg-green-500"
                          : progress < 100
                          ? "bg-yellow-500"
                          : "bg-red-500"
                      }`}
                      style={{
                        width: `${Math.min(progress, 100)}%`,
                      }}
                    />

                  </div>

                </div>

              </div>
            );
          })}
        </div>
      )}
    </div>
  );
};

export default CategoryBudget;